  ccxt::any safeMarket(ccxt::any marketId = ccxt::any{},
                       ccxt::any market = ccxt::any{},
                       ccxt::any delimiter = ccxt::any{},
                       ccxt::any marketType = ccxt::any{}) override {
    // bithumb has a different type of conflict in markets, because
    // their ids are the base currency (BTC for instance), so we can have
    // multiple "BTC" ids representing the different markets (BTC/ETH,
    // "BTC/DOGE", etc) since they're the same we just need to return one
    return Exchange::safeMarket(marketId, market, delimiter,
                                std::string("spot"));
  }

  ccxt::any amountToPrecision(ccxt::any symbol, ccxt::any amount) override {
    ccxt::any market = this->market(symbol);
    return this->decimalToPrecision(
        amount, TRUNCATE,
        ::getValue(::getValue(market, std::string("precision")),
                   std::string("amount")),
        DECIMAL_PLACES);
  }

  virtual ccxt::any getGen2MarketId(ccxt::any market) {
    ccxt::any marketId = this->safeString(market, std::string("id"));
    if (isTrue(isTrue((!isEqual(marketId, ccxt::any{}))) &&
               isTrue((isGreaterThanOrEqual(
                   getIndexOf(marketId, std::string("-")), 0))))) {
      return marketId;
    }
    ccxt::any quoteId =
        this->safeString2(market, std::string("quoteId"), std::string("quote"));
    ccxt::any baseId =
        this->safeString2(market, std::string("baseId"), std::string("base"));
    return add(add(quoteId, std::string("-")), baseId);
  }

  /**
   * @method
   * @name bithumb#fetchMarkets
   * @description retrieves data on all markets for bithumb
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%ED%98%84%EC%9E%AC%EA%B0%80-%EC%A0%95%EB%B3%B4-%EC%A1%B0%ED%9A%8C-all
   * @see
   * https://apidocs.bithumb.com/reference/%EA%B1%B0%EB%9E%98-%EB%8C%80%EC%83%81-%EB%AA%A9%EB%A1%9D-%EC%A1%B0%ED%9A%8C
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any result = ccxt::list{};
                 ccxt::any request = ccxt::dict{};
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchMarkets"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(isEqual(generation, 2))) {
                   ::setValue(request, std::string("isDetails"), true);
                   ccxt::any response = awaitValue(this->publicGetV1MarketAll(
                       this->extend(request, params)));
                   //
                   //     [
                   //         {
                   //             "market": "KRW-BTC",
                   //             "korean_name": "비트코인",
                   //             "english_name": "Bitcoin",
                   //             "market_warning": "NONE"
                   //         },
                   //     ]
                   //
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(response));
                        postFixIncrement(i)) {
                     ccxt::any entry = ::getValue(response, i);
                     ccxt::any marketId =
                         this->safeString(entry, std::string("market"));
                     ccxt::any baseId = ccxt::any{};
                     ccxt::any quoteId = ccxt::any{};
                     ccxt::any base = ccxt::any{};
                     ccxt::any quote = ccxt::any{};
                     if (isTrue(!isEqual(marketId, ccxt::any{}))) {
                       ccxt::any parts = split(marketId, std::string("-"));
                       // to match gen 1, the quoteId is the first currency
                       // derived from the market id
                       baseId = ::getValue(parts, 1);
                       quoteId = ::getValue(parts, 0);
                       base = this->safeCurrencyCode(baseId);
                       quote = this->safeCurrencyCode(quoteId);
                     }
                     if (isTrue(isTrue((isEqual(base, ccxt::any{}))) ||
                                isTrue((isEqual(quote, ccxt::any{}))))) {
                       continue;
                     }
                     arrayPush(result,
                               ccxt::dict{
                                   {std::string("id"), marketId},
                                   {std::string("symbol"),
                                    add(add(base, std::string("/")), quote)},
                                   {std::string("base"), base},
                                   {std::string("quote"), quote},
                                   {std::string("settle"), ccxt::any{}},
                                   {std::string("baseId"), baseId},
                                   {std::string("quoteId"), quoteId},
                                   {std::string("settleId"), ccxt::any{}},
                                   {std::string("type"), std::string("spot")},
                                   {std::string("spot"), true},
                                   {std::string("margin"), false},
                                   {std::string("swap"), false},
                                   {std::string("future"), false},
                                   {std::string("option"), false},
                                   {std::string("active"), true},
                                   {std::string("contract"), false},
                                   {std::string("linear"), ccxt::any{}},
                                   {std::string("inverse"), ccxt::any{}},
                                   {std::string("contractSize"), ccxt::any{}},
                                   {std::string("expiry"), ccxt::any{}},
                                   {std::string("expiryDatetime"), ccxt::any{}},
                                   {std::string("strike"), ccxt::any{}},
                                   {std::string("optionType"), ccxt::any{}},
                                   {std::string("precision"),
                                    ccxt::dict{
                                        {std::string("amount"),
                                         parseInt(std::string("4"))},
                                        {std::string("price"),
                                         parseInt(std::string("4"))},
                                    }},
                                   {std::string("limits"),
                                    ccxt::dict{
                                        {std::string("leverage"),
                                         ccxt::dict{
                                             {std::string("min"), ccxt::any{}},
                                             {std::string("max"), ccxt::any{}},
                                         }},
                                        {std::string("amount"),
                                         ccxt::dict{
                                             {std::string("min"), ccxt::any{}},
                                             {std::string("max"), ccxt::any{}},
                                         }},
                                        {std::string("price"),
                                         ccxt::dict{
                                             {std::string("min"), ccxt::any{}},
                                             {std::string("max"), ccxt::any{}},
                                         }},
                                        {std::string("cost"),
                                         ccxt::dict{
                                             {std::string("min"), ccxt::any{}},
                                             {std::string("max"), ccxt::any{}},
                                         }},
                                    }},
                                   {std::string("created"), ccxt::any{}},
                                   {std::string("info"), entry},
                               });
                   }
                 } else {
                   ccxt::any quoteCurrencies = this->safeDict(
                       this->options, std::string("quoteCurrencies"),
                       ccxt::dict{});
                   ccxt::any quotes = getObjectKeys(quoteCurrencies);
                   ccxt::any promises = ccxt::list{};
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(quotes));
                        postFixIncrement(i)) {
                     ::setValue(request, std::string("quoteId"),
                                ::getValue(quotes, i));
                     arrayPush(promises, this->publicGetPublicTickerALLQuoteId(
                                             this->extend(request, params)));
                   }
                   ccxt::any results = awaitValue(promiseAll(promises));
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(quotes));
                        postFixIncrement(i)) {
                     ccxt::any quote = ::getValue(quotes, i);
                     ccxt::any quoteId = quote;
                     ccxt::any response = ::getValue(results, i);
                     ccxt::any data = this->safeDict(
                         response, std::string("data"), ccxt::dict{});
                     ccxt::any extension =
                         this->safeDict(quoteCurrencies, quote, ccxt::dict{});
                     ccxt::any currencyIds = getObjectKeys(data);
                     for (ccxt::any j = 0;
                          isLessThan(j, getArrayLength(currencyIds));
                          postFixIncrement(j)) {
                       ccxt::any currencyId = ::getValue(currencyIds, j);
                       if (isTrue(isEqual(currencyId, std::string("date")))) {
                         continue;
                       }
                       ccxt::any market = ::getValue(data, currencyId);
                       ccxt::any base = this->safeCurrencyCode(currencyId);
                       ccxt::any active = true;
                       if (isTrue(isArray(market))) {
                         ccxt::any numElements = getArrayLength(market);
                         if (isTrue(isEqual(numElements, 0))) {
                           active = false;
                         }
                       }
                       ccxt::any entry = this->deepExtend(
                           ccxt::dict{
                               {std::string("id"), currencyId},
                               {std::string("symbol"),
                                add(add(base, std::string("/")), quote)},
                               {std::string("base"), base},
                               {std::string("quote"), quote},
                               {std::string("settle"), ccxt::any{}},
                               {std::string("baseId"), currencyId},
                               {std::string("quoteId"), quoteId},
                               {std::string("settleId"), ccxt::any{}},
                               {std::string("type"), std::string("spot")},
                               {std::string("spot"), true},
                               {std::string("margin"), false},
                               {std::string("swap"), false},
                               {std::string("future"), false},
                               {std::string("option"), false},
                               {std::string("active"), active},
                               {std::string("contract"), false},
                               {std::string("linear"), ccxt::any{}},
                               {std::string("inverse"), ccxt::any{}},
                               {std::string("contractSize"), ccxt::any{}},
                               {std::string("expiry"), ccxt::any{}},
                               {std::string("expiryDatetime"), ccxt::any{}},
                               {std::string("strike"), ccxt::any{}},
                               {std::string("optionType"), ccxt::any{}},
                               {std::string("precision"),
                                ccxt::dict{
                                    {std::string("amount"),
                                     parseInt(std::string("4"))},
                                    {std::string("price"),
                                     parseInt(std::string("4"))},
                                }},
                               {std::string("limits"),
                                ccxt::dict{
                                    {std::string("leverage"),
                                     ccxt::dict{
                                         {std::string("min"), ccxt::any{}},
                                         {std::string("max"), ccxt::any{}},
                                     }},
                                    {std::string("amount"),
                                     ccxt::dict{
                                         {std::string("min"), ccxt::any{}},
                                         {std::string("max"), ccxt::any{}},
                                     }},
                                    {std::string("price"),
                                     ccxt::dict{
                                         {std::string("min"), ccxt::any{}},
                                         {std::string("max"), ccxt::any{}},
                                     }},
                                    {std::string("cost"), ccxt::dict{}},
                                }},
                               {std::string("created"), ccxt::any{}},
                               {std::string("info"), market},
                           },
                           extension);
                       arrayPush(result, entry);
                     }
                   }
                 }
                 return result;
               })
        .share();
  }

  ccxt::any parseBalance(ccxt::any response) override {
    //
    // generation 1
    //
    //     {
    //         "status": "0000",
    //         "data": {
    //             "total_krw": "51026.000000",
    //             "in_use_krw": "0.00000000",
    //             "available_krw": "51026.00000000",
    //         }
    //     }
    //
    // generation 2
    //
    //     [
    //         {
    //             "currency": "KRW",
    //             "balance": "51026",
    //             "locked": "0",
    //             "avg_buy_price": "0",
    //             "avg_buy_price_modified": false,
    //             "unit_currency": "KRW"
    //         },
    //     ]
    //
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
    };
    ccxt::any balances = this->safeDict(response, std::string("data"));
    if (isTrue(!isEqual(balances, ccxt::any{}))) {
      ccxt::any codes = getObjectKeys(this->currencies);
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(codes));
           postFixIncrement(i)) {
        ccxt::any code = ::getValue(codes, i);
        ccxt::any account = this->account();
        ccxt::any currency = this->currency(code);
        ccxt::any lowerCurrencyId =
            this->safeStringLower(currency, std::string("id"));
        ::setValue(account, std::string("total"),
                   this->safeString(
                       balances, add(std::string("total_"), lowerCurrencyId)));
        ::setValue(account, std::string("used"),
                   this->safeString(
                       balances, add(std::string("in_use_"), lowerCurrencyId)));
        ::setValue(account, std::string("free"),
                   this->safeString(balances, add(std::string("available_"),
                                                  lowerCurrencyId)));
        ::setValue(result, code, account);
      }
    } else {
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
           postFixIncrement(i)) {
        ccxt::any entry = ::getValue(response, i);
        ccxt::any account = this->account();
        ccxt::any currencyId = this->safeString(entry, std::string("currency"));
        ccxt::any code = this->safeCurrencyCode(currencyId);
        if (isTrue(isEqual(code, ccxt::any{}))) {
          continue;
        }
        ::setValue(account, std::string("free"),
                   this->safeString(entry, std::string("balance")));
        ::setValue(account, std::string("used"),
                   this->safeString(entry, std::string("locked")));
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name bithumb#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EB%B3%B4%EC%9C%A0%EC%9E%90%EC%82%B0-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%A0%84%EC%B2%B4-%EC%9E%90%EC%82%B0-%EC%A1%B0%ED%9A%8C
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any generation = ccxt::any{};
                        ccxt::any generationparamsVariable =
                            this->handleOptionAndParams(
                                params, std::string("fetchBalance"),
                                std::string("generation"), 2);
                        generation = ::getValue(generationparamsVariable, 0);
                        params = ::getValue(generationparamsVariable, 1);
                        ccxt::any response = ccxt::any{};
                        if (isTrue(isEqual(generation, 2))) {
                          response =
                              awaitValue(this->privateGetV1Accounts(params));
                        } else {
                          ccxt::any request = ccxt::dict{
                              {std::string("currency"), std::string("ALL")},
                          };
                          response = awaitValue(this->privatePostInfoBalance(
                              this->extend(request, params)));
                        }
                        return this->parseBalance(response);
                      })
        .share();
  }

  /**
   * @method
   * @name bithumb#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%ED%98%B8%EA%B0%80-%EC%A0%95%EB%B3%B4-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%ED%98%B8%EA%B0%80-%EC%A1%B0%ED%9A%8C
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchOrderBook"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::any{};
                 ccxt::any timestamp = ccxt::any{};
                 if (isTrue(isEqual(generation, 2))) {
                   ::setValue(request, std::string("markets"),
                              this->getGen2MarketId(market));
                   response = awaitValue(this->publicGetV1Orderbook(
                       this->extend(request, params)));
                   //
                   //     [
                   //         {
                   //             "market": "BTC-USDC",
                   //             "timestamp": 1782807920105,
                   //             "total_ask_size": 40322.8585,
                   //             "total_bid_size": 174206.4577,
                   //             "orderbook_units": [
                   //                 {
                   //                     "ask_price": 0.00001687,
                   //                     "bid_price": 0.0000168,
                   //                     "ask_size": 155,
                   //                     "bid_size": 41.6666
                   //                 },
                   //             ]
                   //         }
                   //     ]
                   //
                   ccxt::any result = this->safeDict(response, 0, ccxt::dict{});
                   timestamp =
                       this->safeInteger(result, std::string("timestamp"));
                   ccxt::any orderBookUnits = this->safeList(
                       result, std::string("orderbook_units"), ccxt::list{});
                   ccxt::any bids = ccxt::list{};
                   ccxt::any asks = ccxt::list{};
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(orderBookUnits));
                        postFixIncrement(i)) {
                     ccxt::any entry = ::getValue(orderBookUnits, i);
                     arrayPush(
                         bids,
                         ccxt::dict{
                             {std::string("price"),
                              this->safeString(entry,
                                               std::string("bid_price"))},
                             {std::string("quantity"),
                              this->safeString(entry, std::string("bid_size"))},
                         });
                     arrayPush(
                         asks,
                         ccxt::dict{
                             {std::string("price"),
                              this->safeString(entry,
                                               std::string("ask_price"))},
                             {std::string("quantity"),
                              this->safeString(entry, std::string("ask_size"))},
                         });
                   }
                   data = ccxt::dict{
                       {std::string("bids"), bids},
                       {std::string("asks"), asks},
                   };
                 } else {
                   ::setValue(request, std::string("baseId"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("quoteId"),
                              ::getValue(market, std::string("quoteId")));
                   if (isTrue(!isEqual(limit, ccxt::any{}))) {
                     ::setValue(request, std::string("count"),
                                limit); // default 30, max 30
                   }
                   response =
                       awaitValue(this->publicGetPublicOrderbookBaseIdQuoteId(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "status":"0000",
                   //         "data":{
                   //             "timestamp":"1587621553942",
                   //             "payment_currency":"KRW",
                   //             "order_currency":"BTC",
                   //             "bids":[
                   //                 {"price":"8652000","quantity":"0.0043"},
                   //                 {"price":"8651000","quantity":"0.0049"},
                   //                 {"price":"8650000","quantity":"8.4791"},
                   //             ],
                   //             "asks":[
                   //                 {"price":"8654000","quantity":"0.119"},
                   //                 {"price":"8655000","quantity":"0.254"},
                   //                 {"price":"8658000","quantity":"0.119"},
                   //             ]
                   //         }
                   //     }
                   //
                   data = this->safeDict(response, std::string("data"),
                                         ccxt::dict{});
                   timestamp =
                       this->safeInteger(data, std::string("timestamp"));
                 }
                 return this->parseOrderBook(
                     data, symbol, timestamp, std::string("bids"),
                     std::string("asks"), std::string("price"),
                     std::string("quantity"));
               })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    // generation 1: fetchTicker, fetchTickers
    //
    //     {
    //         "opening_price":"227100",
    //         "closing_price":"228400",
    //         "min_price":"222300",
    //         "max_price":"230000",
    //         "units_traded":"82618.56075337",
    //         "acc_trade_value":"18767376138.6031",
    //         "prev_closing_price":"227100",
    //         "units_traded_24H":"151871.13484676",
    //         "acc_trade_value_24H":"34247610416.8974",
    //         "fluctate_24H":"8700",
    //         "fluctate_rate_24H":"3.96",
    //         "date":"1587710327264", // fetchTickers inject this
    //     }
    //
    // generation 2: fetchTicker, fetchTickers
    //
    //     {
    //         "market": "BTC-USDC",
    //         "trade_date": "20260701",
    //         "trade_time": "233533",
    //         "trade_date_kst": "20260702",
    //         "trade_time_kst": "083533",
    //         "trade_timestamp": 1782981333650,
    //         "opening_price": 0.00001667,
    //         "high_price": 0.00001667,
    //         "low_price": 0.00001645,
    //         "trade_price": 0.00001659,
    //         "prev_closing_price": 0.00001673,
    //         "change": "FALL",
    //         "change_price": 1.4E-7,
    //         "change_rate": 0.0084,
    //         "signed_change_price": -1.4E-7,
    //         "signed_change_rate": -0.0084,
    //         "trade_volume": 1.43724182,
    //         "acc_trade_price": 0.77934383561689,
    //         "acc_trade_price_24h": 1.76373410121466379999997512,
    //         "acc_trade_volume": 47175.3220805,
    //         "acc_trade_volume_24h": 104565.90238645676844763,
    //         "highest_52_week_price": 0.00006592,
    //         "highest_52_week_date": "2025-11-05",
    //         "lowest_52_week_price": 0.00000782,
    //         "lowest_52_week_date": "2026-02-22",
    //         "timestamp": 1782981333650
    //     }
    //
    // generation 2: watchTicker
    //
    //     {
    //         "type": "ticker",
    //         "code": "KRW-BTC",
    //         "opening_price": 94223000,
    //         "high_price": 95465000,
    //         "low_price": 93601000,
    //         "trade_price": 95299000,
    //         "prev_closing_price": 94201000,
    //         "change": "RISE",
    //         "change_price": 1098000,
    //         "signed_change_price": 1098000,
    //         "change_rate": 0.01165593,
    //         "signed_change_rate": 0.01165593,
    //         "trade_volume": 0.0094,
    //         "acc_trade_volume": 151.44914647,
    //         "acc_trade_volume_24h": 310.44065227,
    //         "acc_trade_price": 14330306973.41015,
    //         "acc_trade_price_24h": 29226371799.56915,
    //         "trade_date": "20260710",
    //         "trade_time": "124548",
    //         "trade_timestamp": 1783655148303,
    //         "ask_bid": "BID",
    //         "acc_ask_volume": 52.30413928,
    //         "acc_bid_volume": 99.14500719,
    //         "highest_52_week_price": 179734000,
    //         "highest_52_week_date": "2025-10-09",
    //         "lowest_52_week_price": 81110000,
    //         "lowest_52_week_date": "2026-02-06",
    //         "market_state": "ACTIVE",
    //         "is_trading_suspended": false,
    //         "delisting_date": "",
    //         "market_warning": "NONE",
    //         "timestamp": 1783655148485,
    //         "stream_type": "REALTIME"
    //     }
    //
    ccxt::any timestamp = this->safeInteger2(ticker, std::string("date"),
                                             std::string("trade_timestamp"));
    ccxt::any marketId = this->safeString(ticker, std::string("market"));
    ccxt::any symbol = this->safeSymbol(marketId, market);
    ccxt::any close = this->safeString2(ticker, std::string("closing_price"),
                                        std::string("trade_price"));
    ccxt::any change =
        this->safeString2(ticker, std::string("signed_change_price"),
                          std::string("change_price"));
    ccxt::any percentage = this->safeString2(
        ticker, std::string("signed_change_rate"), std::string("change_rate"));
    ccxt::any open = this->safeString(ticker, std::string("opening_price"));
    ccxt::any nonZeroOpen = this->omitZero(open);
    if (isTrue(isTrue(isTrue((!isEqual(marketId, ccxt::any{}))) &&
                      isTrue((!isEqual(nonZeroOpen, ccxt::any{})))) &&
               isTrue((!isEqual(close, ccxt::any{}))))) {
      ccxt::any computedChange = ccxt::Precise::stringSub(close, open);
      // Some v2 payloads return signed_change_price as 0 while open/last imply
      // a non-zero move.
      if (isTrue(isTrue(isTrue((!isEqual(change, ccxt::any{}))) &&
                        isTrue(ccxt::Precise::stringEq(change,
                                                       std::string("0")))) &&
                 !isTrue(ccxt::Precise::stringEq(computedChange,
                                                 std::string("0"))))) {
        change = computedChange;
        percentage = ccxt::any{};
      }
    }
    ccxt::any high = this->safeString2(ticker, std::string("max_price"),
                                       std::string("high_price"));
    ccxt::any low = this->safeString2(ticker, std::string("min_price"),
                                      std::string("low_price"));
    // Some generation 2 ticker payloads can contain inconsistent high/low
    // versus last.
    if (isTrue(isTrue(isTrue((!isEqual(close, ccxt::any{}))) &&
                      isTrue((!isEqual(high, ccxt::any{})))) &&
               isTrue(ccxt::Precise::stringGt(close, high)))) {
      high = close;
    }
    if (isTrue(isTrue(isTrue((!isEqual(close, ccxt::any{}))) &&
                      isTrue((!isEqual(low, ccxt::any{})))) &&
               isTrue(ccxt::Precise::stringLt(close, low)))) {
      low = close;
    }
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"), high},
            {std::string("low"), low},
            {std::string("bid"),
             this->safeString(ticker, std::string("buy_price"))},
            {std::string("bidVolume"),
             this->safeString(ticker, std::string("acc_bid_volume"))},
            {std::string("ask"),
             this->safeString(ticker, std::string("sell_price"))},
            {std::string("askVolume"),
             this->safeString(ticker, std::string("acc_ask_volume"))},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), open},
            {std::string("close"), close},
            {std::string("last"), close},
            {std::string("previousClose"),
             this->safeString(ticker, std::string("prev_closing_price"))},
            {std::string("change"), change},
            {std::string("percentage"), percentage},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"),
             this->safeString2(ticker, std::string("units_traded_24H"),
                               std::string("acc_trade_volume_24h"))},
            {std::string("quoteVolume"),
             this->safeString2(ticker, std::string("acc_trade_value_24H"),
                               std::string("acc_trade_price_24h"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name bithumb#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%ED%98%84%EC%9E%AC%EA%B0%80-%EC%A0%95%EB%B3%B4-%EC%A1%B0%ED%9A%8C-all
   * @see
   * https://apidocs.bithumb.com/reference/%ED%98%84%EC%9E%AC%EA%B0%80-%EC%A1%B0%ED%9A%8C
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchTickers"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any result = ccxt::dict{};
                 if (isTrue(isEqual(generation, 2))) {
                   // Bithumb v2 ticker payloads are inconsistent for all-market
                   // calls, so we aggregate 300 markets per request only when
                   // symbols are not provided.
                   ccxt::any marketIds = ccxt::list{};
                   ccxt::any symbolsForMarketIds =
                       (isTrue((isEqual(symbols, ccxt::any{})))
                            ? ccxt::any(this->symbols)
                            : ccxt::any(symbols));
                   ccxt::any symbolsForMarketIdsLength =
                       getArrayLength(symbolsForMarketIds);
                   for (ccxt::any i = 0;
                        isLessThan(i, symbolsForMarketIdsLength);
                        postFixIncrement(i)) {
                     ccxt::any market =
                         this->market(::getValue(symbolsForMarketIds, i));
                     arrayPush(marketIds, this->getGen2MarketId(market));
                   }
                   ccxt::any marketIdsLength = getArrayLength(marketIds);
                   if (isTrue(isEqual(marketIdsLength, 0))) {
                     return result;
                   }
                   ccxt::any marketIdsChunks = ccxt::list{};
                   ccxt::any promises = ccxt::list{};
                   if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                     ::setValue(request, std::string("markets"),
                                join(marketIds, std::string(",")));
                     arrayPush(marketIdsChunks, marketIds);
                     arrayPush(promises, this->publicGetV1Ticker(
                                             this->extend(request, params)));
                   } else {
                     ccxt::any maxMarketIdsPerRequest = this->safeInteger(
                         this->options,
                         std::string(
                             "fetchTickersGeneration2MaxMarketIdsPerRequest"),
                         300);
                     if (isTrue(
                             isTrue((isEqual(maxMarketIdsPerRequest,
                                             ccxt::any{}))) ||
                             isTrue((isLessThan(maxMarketIdsPerRequest, 1))))) {
                       maxMarketIdsPerRequest = 300;
                     }
                     ccxt::any marketIdsChunk = ccxt::list{};
                     for (ccxt::any i = 0; isLessThan(i, marketIdsLength);
                          postFixIncrement(i)) {
                       arrayPush(marketIdsChunk, ::getValue(marketIds, i));
                       ccxt::any marketIdsChunkLength =
                           getArrayLength(marketIdsChunk);
                       ccxt::any isLastMarketId =
                           (isEqual(i, (subtract(marketIdsLength, 1))));
                       if (isTrue(isTrue((isGreaterThanOrEqual(
                                      marketIdsChunkLength,
                                      maxMarketIdsPerRequest))) ||
                                  isTrue(isLastMarketId))) {
                         arrayPush(marketIdsChunks, marketIdsChunk);
                         ::setValue(request, std::string("markets"),
                                    join(marketIdsChunk, std::string(",")));
                         arrayPush(promises,
                                   this->publicGetV1Ticker(
                                       this->extend(request, params)));
                         marketIdsChunk = ccxt::list{};
                       }
                     }
                   }
                   //
                   //     [
                   //         {
                   //             "market": "BTC-USDC",
                   //             "trade_date": "20260701",
                   //             "trade_time": "233533",
                   //             "trade_date_kst": "20260702",
                   //             "trade_time_kst": "083533",
                   //             "trade_timestamp": 1782981333650,
                   //             "opening_price": 0.00001667,
                   //             "high_price": 0.00001667,
                   //             "low_price": 0.00001645,
                   //             "trade_price": 0.00001659,
                   //             "prev_closing_price": 0.00001673,
                   //             "change": "FALL",
                   //             "change_price": 1.4E-7,
                   //             "change_rate": 0.0084,
                   //             "signed_change_price": -1.4E-7,
                   //             "signed_change_rate": -0.0084,
                   //             "trade_volume": 1.43724182,
                   //             "acc_trade_price": 0.77934383561689,
                   //             "acc_trade_price_24h": 1.76373410121466379999997512,
                   //             "acc_trade_volume": 47175.3220805,
                   //             "acc_trade_volume_24h":
                   //             104565.90238645676844763,
                   //             "highest_52_week_price": 0.00006592,
                   //             "highest_52_week_date": "2025-11-05",
                   //             "lowest_52_week_price": 0.00000782,
                   //             "lowest_52_week_date": "2026-02-22",
                   //             "timestamp": 1782981333650
                   //         },
                   //     ]
                   //
                   ccxt::any responses = awaitValue(promiseAll(promises));
                   ccxt::any responsesLength = getArrayLength(responses);
                   for (ccxt::any i = 0; isLessThan(i, responsesLength);
                        postFixIncrement(i)) {
                     ccxt::any response = ::getValue(responses, i);
                     if (isTrue(isTrue(isTrue(this->isDictionary(response)) &&
                                       isTrue((inOp(response,
                                                    std::string("data"))))) &&
                                isTrue((!isEqual(
                                    ::getValue(response, std::string("data")),
                                    ccxt::any{}))))) {
                       response = ::getValue(response, std::string("data"));
                     }
                     ccxt::any expectedMarketId = ccxt::any{};
                     ccxt::any marketIdsChunk =
                         this->safeList(marketIdsChunks, i, ccxt::list{});
                     ccxt::any firstMarketId =
                         this->safeString(marketIdsChunk, 0);
                     if (isTrue(
                             isTrue((!isEqual(firstMarketId, ccxt::any{}))) &&
                             isTrue(
                                 (isEqual(this->safeString(marketIdsChunk, 1),
                                          ccxt::any{}))))) {
                       expectedMarketId = firstMarketId;
                     }
                     ccxt::any tickers = ccxt::list{};
                     if (isTrue(isArray(response))) {
                       tickers = response;
                     } else if (isTrue(this->isDictionary(response))) {
                       if (isTrue(
                               isTrue(
                                   isTrue((inOp(response,
                                                std::string("market")))) ||
                                   isTrue((inOp(response,
                                                std::string("trade_date"))))) ||
                               isTrue(
                                   (inOp(response,
                                         std::string("trade_timestamp")))))) {
                         tickers = ccxt::list{response};
                       } else {
                         ccxt::any ids = getObjectKeys(response);
                         for (ccxt::any j = 0;
                              isLessThan(j, getArrayLength(ids));
                              postFixIncrement(j)) {
                           ccxt::any id = ::getValue(ids, j);
                           ccxt::any ticker = this->safeDict(response, id);
                           if (isTrue(!isEqual(ticker, ccxt::any{}))) {
                             ::setValue(ticker, std::string("market"),
                                        this->safeString(
                                            ticker, std::string("market"), id));
                             arrayPush(tickers, ticker);
                           }
                         }
                       }
                     }
                     for (ccxt::any j = 0;
                          isLessThan(j, getArrayLength(tickers));
                          postFixIncrement(j)) {
                       ccxt::any entry = ::getValue(tickers, j);
                       ccxt::any marketId = this->safeString(
                           entry, std::string("market"), expectedMarketId);
                       if (isTrue(isEqual(marketId, ccxt::any{}))) {
                         continue;
                       }
                       ccxt::any market = this->safeMarket(marketId);
                       ccxt::any symbol = this->safeSymbol(marketId, market);
                       if (isTrue(isEqual(symbol, ccxt::any{}))) {
                         continue;
                       }
                       ::setValue(result, symbol,
                                  this->parseTicker(entry, market));
                     }
                   }
                 } else {
                   ccxt::any quoteCurrencies = this->safeDict(
                       this->options, std::string("quoteCurrencies"),
                       ccxt::dict{});
                   ccxt::any quotes = getObjectKeys(quoteCurrencies);
                   if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                     ccxt::any requiredQuotes = ccxt::dict{};
                     for (ccxt::any i = 0;
                          isLessThan(i, getArrayLength(symbols));
                          postFixIncrement(i)) {
                       ccxt::any symbol = ::getValue(symbols, i);
                       ccxt::any market = this->market(symbol);
                       ccxt::any quoteId =
                           this->safeString(market, std::string("quoteId"));
                       if (isTrue(isTrue((!isEqual(quoteId, ccxt::any{}))) &&
                                  isTrue((inOp(quoteCurrencies, quoteId))))) {
                         ::setValue(requiredQuotes, quoteId, true);
                       }
                     }
                     ccxt::any requiredQuoteIds = getObjectKeys(requiredQuotes);
                     ccxt::any populatedQuotes =
                         this->safeString(requiredQuoteIds, 0);
                     if (isTrue(!isEqual(populatedQuotes, ccxt::any{}))) {
                       quotes = requiredQuoteIds;
                     }
                   }
                   ccxt::any promises = ccxt::list{};
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(quotes));
                        postFixIncrement(i)) {
                     ::setValue(request, std::string("quoteId"),
                                ::getValue(quotes, i));
                     arrayPush(promises, this->publicGetPublicTickerALLQuoteId(
                                             this->extend(request, params)));
                   }
                   ccxt::any responses = awaitValue(promiseAll(promises));
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(quotes));
                        postFixIncrement(i)) {
                     ccxt::any quote = ::getValue(quotes, i);
                     ccxt::any response = ::getValue(responses, i);
                     ccxt::any data = this->safeDict(
                         response, std::string("data"), ccxt::dict{});
                     ccxt::any timestamp =
                         this->safeInteger(data, std::string("date"));
                     ccxt::any tickers = this->omit(data, std::string("date"));
                     ccxt::any currencyIds = getObjectKeys(tickers);
                     for (ccxt::any j = 0;
                          isLessThan(j, getArrayLength(currencyIds));
                          postFixIncrement(j)) {
                       ccxt::any currencyId = ::getValue(currencyIds, j);
                       ccxt::any ticker = ::getValue(data, currencyId);
                       ccxt::any base = this->safeCurrencyCode(currencyId);
                       ccxt::any symbol =
                           add(add(base, std::string("/")), quote);
                       ccxt::any market = this->safeMarket(symbol);
                       ::setValue(ticker, std::string("date"), timestamp);
                       ::setValue(result, symbol,
                                  this->parseTicker(ticker, market));
                     }
                   }
                 }
                 return this->filterByArrayTickers(
                     result, std::string("symbol"), symbols);
               })
        .share();
  }

  /**
   * @method
   * @name bithumb#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%ED%98%84%EC%9E%AC%EA%B0%80-%EC%A0%95%EB%B3%B4-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%ED%98%84%EC%9E%AC%EA%B0%80-%EC%A1%B0%ED%9A%8C
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchTicker"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::dict{};
                 if (isTrue(isEqual(generation, 2))) {
                   ::setValue(request, std::string("markets"),
                              this->getGen2MarketId(market));
                   response = awaitValue(
                       this->publicGetV1Ticker(this->extend(request, params)));
                   //
                   //     [
                   //         {
                   //             "market": "BTC-USDC",
                   //             "trade_date": "20260701",
                   //             "trade_time": "233533",
                   //             "trade_date_kst": "20260702",
                   //             "trade_time_kst": "083533",
                   //             "trade_timestamp": 1782981333650,
                   //             "opening_price": 0.00001667,
                   //             "high_price": 0.00001667,
                   //             "low_price": 0.00001645,
                   //             "trade_price": 0.00001659,
                   //             "prev_closing_price": 0.00001673,
                   //             "change": "FALL",
                   //             "change_price": 1.4E-7,
                   //             "change_rate": 0.0084,
                   //             "signed_change_price": -1.4E-7,
                   //             "signed_change_rate": -0.0084,
                   //             "trade_volume": 1.43724182,
                   //             "acc_trade_price": 0.77934383561689,
                   //             "acc_trade_price_24h": 1.76373410121466379999997512,
                   //             "acc_trade_volume": 47175.3220805,
                   //             "acc_trade_volume_24h":
                   //             104565.90238645676844763,
                   //             "highest_52_week_price": 0.00006592,
                   //             "highest_52_week_date": "2025-11-05",
                   //             "lowest_52_week_price": 0.00000782,
                   //             "lowest_52_week_date": "2026-02-22",
                   //             "timestamp": 1782981333650
                   //         },
                   //     ]
                   //
                   data = this->safeDict(response, 0, ccxt::dict{});
                 } else {
                   ::setValue(request, std::string("baseId"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("quoteId"),
                              ::getValue(market, std::string("quoteId")));
                   response =
                       awaitValue(this->publicGetPublicTickerBaseIdQuoteId(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "status":"0000",
                   //         "data":{
                   //             "opening_price":"227100",
                   //             "closing_price":"228400",
                   //             "min_price":"222300",
                   //             "max_price":"230000",
                   //             "units_traded":"82618.56075337",
                   //             "acc_trade_value":"18767376138.6031",
                   //             "prev_closing_price":"227100",
                   //             "units_traded_24H":"151871.13484676",
                   //             "acc_trade_value_24H":"34247610416.8974",
                   //             "fluctate_24H":"8700",
                   //             "fluctate_rate_24H":"3.96",
                   //             "date":"1587710327264"
                   //         }
                   //     }
                   //
                   data = this->safeDict(response, std::string("data"),
                                         ccxt::dict{});
                 }
                 return this->parseTicker(data, market);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    // generation 1
    //
    //     [
    //         1576823400000, // 기준 시간
    //         "8284000", // 시가
    //         "8286000", // 종가
    //         "8289000", // 고가
    //         "8276000", // 저가
    //         "15.41503692" // 거래량
    //     ]
    //
    // generation 2
    //
    //     {
    //         "market": "BTC-USDC",
    //         "candle_date_time_utc": "2026-07-02T08:59:00",
    //         "candle_date_time_kst": "2026-07-02T17:59:00",
    //         "opening_price": 0.0000165,
    //         "high_price": 0.0000165,
    //         "low_price": 0.0000165,
    //         "trade_price": 0.0000165,
    //         "timestamp": 1782982784329,
    //         "candle_acc_trade_price": 0.001155,
    //         "candle_acc_trade_volume": 70,
    //         "unit": 1
    //     }
    //
    ccxt::any timestamp = ccxt::any{};
    if (isTrue(isArray(ohlcv))) {
      timestamp = this->safeInteger2(ohlcv, 0, std::string("timestamp"));
    } else {
      timestamp = this->parse8601(
          this->safeString2(ohlcv, std::string("candle_date_time_utc"),
                            std::string("candle_date_time_kst")));
    }
    return ccxt::list{
        timestamp,
        this->safeNumber2(ohlcv, 1, std::string("opening_price")),
        this->safeNumber2(ohlcv, 3, std::string("high_price")),
        this->safeNumber2(ohlcv, 4, std::string("low_price")),
        this->safeNumber2(ohlcv, 2, std::string("trade_price")),
        this->safeNumber2(ohlcv, 5, std::string("candle_acc_trade_volume"))};
  }

  /**
   * @method
   * @name bithumb#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://apidocs.bithumb.com/v1.2.0/reference/candlestick-rest-api
   * @see
   * https://apidocs.bithumb.com/reference/%EB%B6%84minute-%EC%BA%94%EB%93%A4-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%9D%BCday-%EC%BA%94%EB%93%A4-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%A3%BCweek-%EC%BA%94%EB%93%A4-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%9B%94month-%EC%BA%94%EB%93%A4-%EC%A1%B0%ED%9A%8C
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchOHLCV"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::list{};
                 if (isTrue(isEqual(generation, 2))) {
                   ::setValue(request, std::string("market"),
                              this->getGen2MarketId(market));
                   if (isTrue(!isEqual(limit, ccxt::any{}))) {
                     ::setValue(request, std::string("count"), limit);
                   }
                   if (isTrue(isEqual(timeframe, std::string("1d")))) {
                     response = awaitValue(this->publicGetV1CandlesDays(
                         this->extend(request, params)));
                   } else if (isTrue(isEqual(timeframe, std::string("1w")))) {
                     response = awaitValue(this->publicGetV1CandlesWeeks(
                         this->extend(request, params)));
                   } else if (isTrue(isEqual(timeframe, std::string("1M")))) {
                     response = awaitValue(this->publicGetV1CandlesMonths(
                         this->extend(request, params)));
                   } else {
                     ccxt::any timeframeInteger =
                         this->safeInteger(this->timeframes, timeframe);
                     if (isTrue(isEqual(timeframeInteger, ccxt::any{}))) {
                       throw BadRequest(toString(
                           add(add(this->id,
                                   std::string(
                                       " fetchOHLCV() unsupported timeframe ")),
                               timeframe)));
                     }
                     ::setValue(request, std::string("unit"), timeframeInteger);
                     response = awaitValue(this->publicGetV1CandlesMinutesUnit(
                         this->extend(request, params)));
                   }
                   //
                   //     [
                   //         {
                   //             "market": "BTC-USDC",
                   //             "candle_date_time_utc": "2026-07-02T08:59:00",
                   //             "candle_date_time_kst": "2026-07-02T17:59:00",
                   //             "opening_price": 0.0000165,
                   //             "high_price": 0.0000165,
                   //             "low_price": 0.0000165,
                   //             "trade_price": 0.0000165,
                   //             "timestamp": 1782982784329,
                   //             "candle_acc_trade_price": 0.001155,
                   //             "candle_acc_trade_volume": 70,
                   //             "unit": 1
                   //         },
                   //     ]
                   //
                   data = response;
                 } else {
                   ccxt::any legacyTimeframes = ccxt::dict{
                       {std::string("1m"), std::string("1m")},
                       {std::string("3m"), std::string("3m")},
                       {std::string("5m"), std::string("5m")},
                       {std::string("10m"), std::string("10m")},
                       {std::string("30m"), std::string("30m")},
                       {std::string("1h"), std::string("1h")},
                       {std::string("6h"), std::string("6h")},
                       {std::string("12h"), std::string("12h")},
                       {std::string("1d"), std::string("24h")},
                       {std::string("1w"), std::string("1w")},
                       {std::string("1M"), std::string("1mm")},
                   };
                   ::setValue(request, std::string("interval"),
                              this->safeString(legacyTimeframes, timeframe,
                                               timeframe));
                   ::setValue(request, std::string("baseId"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("quoteId"),
                              ::getValue(market, std::string("quoteId")));
                   response = awaitValue(
                       this->publicGetPublicCandlestickBaseIdQuoteIdInterval(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "status": "0000",
                   //         "data": {
                   //             [
                   //                 1576823400000, // 기준 시간
                   //                 "8284000", // 시가
                   //                 "8286000", // 종가
                   //                 "8289000", // 고가
                   //                 "8276000", // 저가
                   //                 "15.41503692" // 거래량
                   //             ],
                   //             [
                   //                 1576824000000, // 기준 시간
                   //                 "8284000", // 시가
                   //                 "8281000", // 종가
                   //                 "8289000", // 고가
                   //                 "8275000", // 저가
                   //                 "6.19584467" // 거래량
                   //             ],
                   //         }
                   //     }
                   //
                   data = this->safeList(response, std::string("data"),
                                         ccxt::list{});
                 }
                 return this->parseOHLCVs(data, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // generation 1: fetchTrades (public)
    //
    //     {
    //         "transaction_date":"2020-04-23 22:21:46",
    //         "type":"ask",
    //         "units_traded":"0.0125",
    //         "price":"8667000",
    //         "total":"108337"
    //     }
    //
    // generation 1: fetchOrder (private)
    //
    //     {
    //         "transaction_date": "1572497603902030",
    //         "price": "8601000",
    //         "units": "0.005",
    //         "fee_currency": "KRW",
    //         "fee": "107.51",
    //         "total": "43005"
    //     }
    //
    // generation 2: fetchTrades
    //
    //     {
    //         "market": "BTC-USDC",
    //         "trade_date_utc": "2026-07-02",
    //         "trade_time_utc": "08:41:10",
    //         "timestamp": "1782981670705",
    //         "trade_price": "0.00001646",
    //         "trade_volume": "42.0335581",
    //         "prev_closing_price": "0.00001673",
    //         "change_price": "-2.7E-7",
    //         "ask_bid": "ASK",
    //         "sequential_id": "17829816707050000"
    //     }
    //
    // generation 2: watchTrades
    //
    //     {
    //         "type": "trade",
    //         "code": "KRW-BTC",
    //         "trade_price": 95539000,
    //         "trade_volume": 0.00022664,
    //         "ask_bid": "ASK",
    //         "prev_closing_price": 94201000,
    //         "change": "RISE",
    //         "change_price": 1338000,
    //         "trade_date": "2026-07-10",
    //         "trade_time": "13:39:41",
    //         "trade_timestamp": 1783658381138,
    //         "sequential_id": "862683813820523888",
    //         "timestamp": 1783658381398,
    //         "stream_type": "REALTIME"
    //     }
    //
    // a workaround for their bug in date format, hours are not 0-padded
    ccxt::any timestamp = this->safeInteger(trade, std::string("timestamp"));
    ccxt::any isGenerationTwo = (!isEqual(timestamp, ccxt::any{}));
    ccxt::any transactionDatetime =
        this->safeString(trade, std::string("transaction_date"));
    if (isTrue(!isEqual(transactionDatetime, ccxt::any{}))) {
      ccxt::any parts = split(transactionDatetime, std::string(" "));
      ccxt::any numParts = getArrayLength(parts);
      if (isTrue(isGreaterThan(numParts, 1))) {
        ccxt::any transactionDate = ::getValue(parts, 0);
        ccxt::any transactionTime = ::getValue(parts, 1);
        if (isTrue(isLessThan(getStringLength(transactionTime), 8))) {
          transactionTime = add(std::string("0"), transactionTime);
        }
        timestamp = this->parse8601(
            add(add(transactionDate, std::string(" ")), transactionTime));
      } else {
        timestamp = this->safeIntegerProduct(
            trade, std::string("transaction_date"), 0.001);
      }
    }
    if (isTrue(isTrue((!isEqual(timestamp, ccxt::any{}))) &&
               isTrue((!isTrue(isGenerationTwo))))) {
      timestamp = subtract(
          timestamp,
          multiply(
              9,
              3600000)); // they report UTC + 9 hours, server in Korean timezone
    }
    ccxt::any type = ccxt::any{};
    ccxt::any side = this->safeStringLower2(trade, std::string("ask_bid"),
                                            std::string("type"));
    if (isTrue(isEqual(side, std::string("bid")))) {
      side = std::string("buy");
    } else if (isTrue(isEqual(side, std::string("ask")))) {
      side = std::string("sell");
    } else {
      side = ccxt::any{};
    }
    ccxt::any id = this->safeString2(trade, std::string("cont_no"),
                                     std::string("sequential_id"));
    ccxt::any marketId = this->safeString(trade, std::string("market"));
    market = this->safeMarket(marketId, market);
    ccxt::any priceString = this->safeString2(trade, std::string("price"),
                                              std::string("trade_price"));
    ccxt::any amountString =
        this->safeString(trade, std::string("trade_volume"));
    if (isTrue(isEqual(amountString, ccxt::any{}))) {
      amountString = this->fixCommaNumber(this->safeString2(
          trade, std::string("units_traded"), std::string("units")));
    }
    ccxt::any costString = this->safeString(trade, std::string("total"));
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCostString = this->safeString(trade, std::string("fee"));
    if (isTrue(!isEqual(feeCostString, ccxt::any{}))) {
      ccxt::any feeCurrencyId =
          this->safeString(trade, std::string("fee_currency"));
      ccxt::any feeCurrencyCode = this->commonCurrencyCode(feeCurrencyId);
      fee = ccxt::dict{
          {std::string("cost"), feeCostString},
          {std::string("currency"), feeCurrencyCode},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("order"), ccxt::any{}},
            {std::string("type"), type},
            {std::string("side"), side},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), costString},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name bithumb#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EC%B5%9C%EA%B7%BC-%EC%B2%B4%EA%B2%B0-%EB%82%B4%EC%97%AD
   * @see
   * https://apidocs.bithumb.com/reference/%EC%B2%B4%EA%B2%B0-%EB%82%B4%EC%97%AD-%EC%A1%B0%ED%9A%8C
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchTrades"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("count"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::list{};
                 if (isTrue(isEqual(generation, 2))) {
                   ::setValue(request, std::string("market"),
                              this->getGen2MarketId(market));
                   response = awaitValue(this->publicGetV1TradesTicks(
                       this->extend(request, params)));
                   //
                   //     [
                   //         {
                   //             "market": "BTC-USDC",
                   //             "trade_date_utc": "2026-07-02",
                   //             "trade_time_utc": "08:41:10",
                   //             "timestamp": "1782981670705",
                   //             "trade_price": "0.00001646",
                   //             "trade_volume": "42.0335581",
                   //             "prev_closing_price": "0.00001673",
                   //             "change_price": "-2.7E-7",
                   //             "ask_bid": "ASK",
                   //             "sequential_id": "17829816707050000"
                   //         }
                   //     ]
                   //
                   data = response;
                 } else {
                   ::setValue(request, std::string("baseId"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("quoteId"),
                              ::getValue(market, std::string("quoteId")));
                   response = awaitValue(
                       this->publicGetPublicTransactionHistoryBaseIdQuoteId(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "status":"0000",
                   //         "data":[
                   //             {
                   //                 "transaction_date":"2020-04-23 22:21:46",
                   //                 "type":"ask",
                   //                 "units_traded":"0.0125",
                   //                 "price":"8667000",
                   //                 "total":"108337"
                   //             },
                   //         ]
                   //     }
                   //
                   data = this->safeList(response, std::string("data"),
                                         ccxt::list{});
                 }
                 return this->parseTrades(data, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name bithumb#createOrders
   * @description create a list of trade orders, only available for the
   * generation 2 API
   * @see
   * https://apidocs.bithumb.com/reference/%EB%8B%A4%EA%B1%B4-%EC%A3%BC%EB%AC%B8-%EC%9A%94%EC%B2%AD
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.timeInForce] supports 'IOC', 'FOK', and 'PO'
   * @param {bool} [params.postOnly] true or false
   * @param {string} [params.clientOrderId] the clientOrderId of the order
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrders(ccxt::any orders, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("createOrders"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" createOrders is only supported "
                                             "for the generation 2 API"))));
                 }
                 ccxt::any ordersCount = getArrayLength(orders);
                 if (isTrue(isEqual(ordersCount, 0))) {
                   throw ArgumentsRequired(toString(
                       add(this->id, std::string(" createOrders() requires a "
                                                 "non-empty orders array"))));
                 }
                 ccxt::any ordersRequests = ccxt::list{};
                 ccxt::any orderSymbols = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   ccxt::any rawOrder = ::getValue(orders, i);
                   ccxt::any symbol =
                       this->safeString(rawOrder, std::string("symbol"));
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id, std::string(" createOrders() requires each "
                                               "order to have a symbol"))));
                   }
                   arrayPush(orderSymbols, symbol);
                   ccxt::any type =
                       this->safeString(rawOrder, std::string("type"));
                   if (isTrue(isEqual(type, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id, std::string(" createOrders() requires each "
                                               "order to have a type"))));
                   }
                   ccxt::any side =
                       this->safeString(rawOrder, std::string("side"));
                   if (isTrue(isEqual(side, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id, std::string(" createOrders() requires each "
                                               "order to have a side"))));
                   }
                   ccxt::any amount =
                       this->safeValue(rawOrder, std::string("amount"));
                   ccxt::any price =
                       this->safeValue(rawOrder, std::string("price"));
                   ccxt::any orderParams = this->safeDict(
                       rawOrder, std::string("params"), ccxt::dict{});
                   ccxt::any orderRequest = this->createOrderRequest(
                       symbol, type, side, amount, price, orderParams);
                   arrayPush(ordersRequests, orderRequest);
                 }
                 orderSymbols = this->marketSymbols(orderSymbols, ccxt::any{},
                                                    false, true, true);
                 ccxt::any market = this->market(::getValue(orderSymbols, 0));
                 ccxt::any request = ccxt::dict{
                     {std::string("batch_orders"), ordersRequests},
                 };
                 ccxt::any response = awaitValue(this->privatePostV2OrdersBatch(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "batch_orders_response": [
                 //             {
                 //                 "order_id": "C0101000003152500274",
                 //                 "market": "KRW-BTC",
                 //                 "side": "bid",
                 //                 "order_type": "limit",
                 //                 "created_at": "2026-07-04T15:49:24+09:00",
                 //                 "stp_type": "cancel_taker"
                 //             },
                 //         ]
                 //     }
                 //
                 ccxt::any data = this->safeList(
                     response, std::string("batch_orders_response"),
                     ccxt::list{});
                 return this->parseOrders(data, market);
               })
        .share();
  }

  virtual ccxt::any createOrderRequest(ccxt::any symbol, ccxt::any type,
                                       ccxt::any side, ccxt::any amount,
                                       ccxt::any price = ccxt::any{},
                                       ccxt::any params = ccxt::dict{}) {
    /**
     * @method
     * @ignore
     * @name bithumb#createOrderRequest
     * @description helper function to build the request *for generation 2
     * createOrder and createOrders only*
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much you want to trade in units of the base
     * currency
     * @param {float} [price] the price that the order is to be fulfilled, in
     * units of the quote currency
     * @param {object} [params] extra parameters specific to the exchange API
     * endpoint
     * @returns {object} request to be sent to the exchange
     */
    ccxt::any market = this->market(symbol);
    ccxt::any request = ccxt::dict{
        {std::string("market"), this->getGen2MarketId(market)},
    };
    ccxt::any sideRequest = ccxt::any{};
    if (isTrue(isEqual(side, std::string("buy")))) {
      sideRequest = std::string("bid");
    } else if (isTrue(isEqual(side, std::string("sell")))) {
      sideRequest = std::string("ask");
    } else {
      throw InvalidOrder(toString(add(
          add(this->id, std::string(" createOrder() invalid side ")), side)));
    }
    ::setValue(request, std::string("side"), sideRequest);
    ccxt::any timeInForce = this->safeString2(
        params, std::string("timeInForce"), std::string("time_in_force"));
    if (isTrue(isEqual(timeInForce, ccxt::any{}))) {
      timeInForce = std::string("GTC");
    } else {
      params = this->omit(params, std::string("timeInForce"));
    }
    ccxt::any postOnly = false;
    ccxt::any postOnlyparamsVariable = this->handlePostOnly(
        isEqual(type, std::string("market")), false, params);
    postOnly = ::getValue(postOnlyparamsVariable, 0);
    params = ::getValue(postOnlyparamsVariable, 1);
    if (isTrue(isTrue(postOnly) ||
               isTrue((isEqual(timeInForce, std::string("PO")))))) {
      ::setValue(request, std::string("time_in_force"),
                 std::string("post_only"));
      params = this->omit(params, std::string("postOnly"));
    } else if (isTrue(isEqual(timeInForce, std::string("FOK")))) {
      ::setValue(request, std::string("time_in_force"), std::string("fok"));
    } else if (isTrue(isEqual(timeInForce, std::string("IOC")))) {
      ::setValue(request, std::string("time_in_force"), std::string("ioc"));
    }
    if (isTrue(isEqual(type, std::string("limit")))) {
      ::setValue(request, std::string("price"),
                 this->priceToPrecision(symbol, price));
      ::setValue(request, std::string("volume"),
                 this->amountToPrecision(symbol, amount));
      ::setValue(request, std::string("order_type"), std::string("limit"));
    } else {
      ccxt::any typeRequest = ccxt::any{};
      if (isTrue(isEqual(side, std::string("buy")))) {
        typeRequest = std::string("price");
        // for market buy it requires the amount of quote currency to spend
        ccxt::any cost = this->safeString(params, std::string("cost"));
        params = this->omit(params, std::string("cost"));
        ccxt::any createMarketBuyOrderRequiresPrice = true;
        ccxt::any createMarketBuyOrderRequiresPriceparamsVariable =
            this->handleOptionAndParams(
                params, std::string("createOrder"),
                std::string("createMarketBuyOrderRequiresPrice"), true);
        createMarketBuyOrderRequiresPrice =
            ::getValue(createMarketBuyOrderRequiresPriceparamsVariable, 0);
        params = ::getValue(createMarketBuyOrderRequiresPriceparamsVariable, 1);
        if (isTrue(createMarketBuyOrderRequiresPrice)) {
          if (isTrue(isTrue((isEqual(price, ccxt::any{}))) &&
                     isTrue((isEqual(cost, ccxt::any{}))))) {
            throw InvalidOrder(toString(
                add(this->id,
                    std::string(" createOrder() requires the price argument "
                                "for market buy orders to calculate the total "
                                "cost to spend (amount * price), alternatively "
                                "set the createMarketBuyOrderRequiresPrice "
                                "option or param to false and pass the cost to "
                                "spend in the amount argument"))));
          } else {
            ccxt::any amountString = this->numberToString(amount);
            ccxt::any priceString = this->numberToString(price);
            cost = ccxt::Precise::stringMul(amountString, priceString);
          }
        } else {
          cost = (isTrue((isEqual(cost, ccxt::any{})))
                      ? ccxt::any(this->numberToString(amount))
                      : ccxt::any(cost));
        }
        ::setValue(request, std::string("price"),
                   this->priceToPrecision(symbol, cost));
      } else {
        ::setValue(request, std::string("volume"),
                   this->amountToPrecision(symbol, amount));
        typeRequest = std::string("market");
      }
      ::setValue(request, std::string("order_type"), typeRequest);
    }
    ccxt::any clientOrderId = this->safeString2(
        params, std::string("clientOrderId"), std::string("client_order_id"));
    if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
      ::setValue(request, std::string("client_order_id"), clientOrderId);
      params = this->omit(params, std::string("clientOrderId"));
    }
    return this->extend(request, params);
  }

  /**
   * @method
   * @name bithumb#createOrder
   * @description create a trade order
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EC%A7%80%EC%A0%95%EA%B0%80-%EC%A3%BC%EB%AC%B8%ED%95%98%EA%B8%B0
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EC%8B%9C%EC%9E%A5%EA%B0%80-%EB%A7%A4%EC%88%98%ED%95%98%EA%B8%B0
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EC%8B%9C%EC%9E%A5%EA%B0%80-%EB%A7%A4%EB%8F%84%ED%95%98%EA%B8%B0
   * @see
   * https://apidocs.bithumb.com/reference/%EC%A3%BC%EB%AC%B8-%EC%9A%94%EC%B2%AD
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.timeInForce] supports 'IOC', 'FOK', and 'PO'
   * @param {bool} [params.postOnly] true or false
   * @param {string} [params.clientOrderId] the clientOrderId of the order
   * @param {string} [params.cost] *generation 2 only* optional cost parameter
   * for market buy orders instead of setting the price, must also set
   * createMarketBuyOrderRequiresPrice to false
   * @param {bool} [params.createMarketBuyOrderRequiresPrice] *generation 2
   * only* set to false if passing a cost param or using cost in the amount
   * argument, defaults to true
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("createOrder"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = this->market(symbol);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(generation, 2))) {
                   request = this->createOrderRequest(symbol, type, side,
                                                      amount, price, params);
                   response = awaitValue(this->privatePostV2Orders(request));
                 } else {
                   ::setValue(request, std::string("order_currency"),
                              ::getValue(market, std::string("base")));
                   ::setValue(request, std::string("payment_currency"),
                              ::getValue(market, std::string("quote")));
                   ::setValue(request, std::string("units"),
                              this->amountToPrecision(symbol, amount));
                   if (isTrue(isEqual(type, std::string("limit")))) {
                     ::setValue(request, std::string("price"),
                                this->priceToPrecision(symbol, price));
                     ccxt::any typeRequest = ccxt::any{};
                     if (isTrue(isEqual(side, std::string("buy")))) {
                       typeRequest = std::string("bid");
                     } else {
                       typeRequest = std::string("ask");
                     }
                     ::setValue(request, std::string("type"), typeRequest);
                     response = awaitValue(this->privatePostTradePlace(
                         this->extend(request, params)));
                   } else if (isTrue(isEqual(side, std::string("buy")))) {
                     response = awaitValue(this->privatePostTradeMarketBuy(
                         this->extend(request, params)));
                   } else {
                     response = awaitValue(this->privatePostTradeMarketSell(
                         this->extend(request, params)));
                   }
                 }
                 ccxt::any id =
                     this->safeString(response, std::string("order_id"));
                 if (isTrue(isEqual(id, ccxt::any{}))) {
                   throw InvalidOrder(toString(
                       add(this->id,
                           std::string(
                               " createOrder() did not return an order id"))));
                 }
                 return this->extend(this->parseOrder(response, market),
                                     ccxt::dict{
                                         {std::string("info"), response},
                                         {std::string("symbol"), symbol},
                                         {std::string("type"), type},
                                         {std::string("side"), side},
                                         {std::string("id"), id},
                                     });
               })
        .share();
  }

  /**
   * @method
   * @name bithumb#createMarketBuyOrderWithCost
   * @description create a market buy order by providing the symbol and cost
   * @see
   * https://apidocs.bithumb.com/reference/%EC%A3%BC%EB%AC%B8-%EC%9A%94%EC%B2%AD
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createMarketBuyOrderWithCost(ccxt::any symbol, ccxt::any cost,
                               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("createMarketBuyOrderWithCost"),
                         std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(add(
                       this->id,
                       std::string(" createMarketBuyOrderWithCost() is only "
                                   "supported for the generation 2 API"))));
                 }
                 ::setValue(params,
                            std::string("createMarketBuyOrderRequiresPrice"),
                            false);
                 return awaitValue(this->createOrder(
                     symbol, std::string("market"), std::string("buy"), cost,
                     ccxt::any{}, params));
               })
        .share();
  }

  /**
   * @method
   * @name bithumb#createTwapOrder
   * @description create a trade order that is executed as a TWAP order over a
   * specified duration.
   * @see
   * https://apidocs.bithumb.com/reference/twap-%EC%A3%BC%EB%AC%B8-%EC%9A%94%EC%B2%AD
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency, only required for sale
   * @param {int} duration the duration of the TWAP order in milliseconds
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} params.frequency required order interval in seconds, 15,
   * 20, 30, 60 or 120
   * @param {string} [params.price] order price, required for purchase
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createTwapOrder(ccxt::any symbol, ccxt::any side, ccxt::any amount,
                  ccxt::any duration,
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("createTwapOrder"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" createTwapOrder() is only supported "
                                       "for the generation 2 API"))));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any durationString = this->numberToString(duration);
                 ccxt::any durationSeconds = ccxt::Precise::stringDiv(
                     durationString, std::string("1000"));
                 ccxt::any request = ccxt::dict{
                     {std::string("market"), this->getGen2MarketId(market)},
                     {std::string("duration"), durationSeconds},
                 };
                 if (isTrue(!isEqual(amount, ccxt::any{}))) {
                   ::setValue(request, std::string("volume"),
                              this->amountToPrecision(
                                  symbol, amount)); // required for sale
                 }
                 ccxt::any sideRequest = ccxt::any{};
                 if (isTrue(isEqual(side, std::string("buy")))) {
                   sideRequest = std::string("bid");
                 } else {
                   sideRequest = std::string("ask");
                 }
                 ::setValue(request, std::string("side"), sideRequest);
                 ccxt::any response = awaitValue(
                     this->privatePostV1Twap(this->extend(request, params)));
                 //
                 //     {
                 //         "algo_order_id":
                 //         "019f3ed7-4f92-7179-beee-84b4c71e53fa"
                 //     }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name bithumb#fetchOrder
   * @description fetches information on an order made by the user
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EA%B1%B0%EB%9E%98-%EC%A3%BC%EB%AC%B8%EB%82%B4%EC%97%AD-%EC%83%81%EC%84%B8-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EA%B0%9C%EB%B3%84-%EC%A3%BC%EB%AC%B8-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/twap-%EC%A3%BC%EB%AC%B8%EB%82%B4%EC%97%AD-%EC%A1%B0%ED%9A%8C
   * @param {string} id order id
   * @param {string} [symbol] unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] the clientOrderId of the order,
   * alternative to using the order id
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @param {bool} [params.twap] *generation 2 only* if you want to fetch a
   * generation 2 twap order
   * @param {string} [params.state] *generation 2 only* the order state, either
   * wait, watch, done, or cancel. For twap either progress (default), done, or
   * cancel
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchOrder"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any twap =
                     this->safeBool(params, std::string("twap"), false);
                 params = this->omit(params, std::string("twap"));
                 ccxt::any request = ccxt::dict{};
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::any{};
                 if (isTrue(isEqual(generation, 2))) {
                   if (isTrue(twap)) {
                     if (isTrue(!isEqual(market, ccxt::any{}))) {
                       ::setValue(request, std::string("market"),
                                  this->getGen2MarketId(market));
                     }
                     ::setValue(request, std::string("uuids"), ccxt::list{id});
                     response = awaitValue(
                         this->privateGetV1Twap(this->extend(request, params)));
                     //
                     //     {
                     //         "has_next": false,
                     //         "next_key": null,
                     //         "orders": [
                     //             {
                     //                 "uuid":
                     //                 "019f3ed7-4f92-7179-beee-84b4c71e53fa",
                     //                 "side": "bid",
                     //                 "price": "92500000",
                     //                 "state": "progress",
                     //                 "market": "KRW-BTC",
                     //                 "created_at":
                     //                 "2025-12-04T10:00:00+09:00", "volume":
                     //                 "1.0", "total_order_count": 60,
                     //                 "total_trades_count": 10,
                     //                 "progress_count": 25,
                     //                 "total_executed_amount": "2312500000",
                     //                 "total_executed_volume": "0.25",
                     //                 "avg_trade_price": "92500000.000",
                     //                 "wallet_id": "0000000000-00-0000"
                     //             },
                     //         ]
                     //     }
                     //
                     ccxt::any orders = this->safeList(
                         response, std::string("orders"), ccxt::list{});
                     data = this->safeDict(orders, 0, ccxt::dict{});
                   } else {
                     ccxt::any clientOrderId =
                         this->safeString2(params, std::string("clientOrderId"),
                                           std::string("client_order_id"));
                     if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                       ::setValue(request, std::string("client_order_id"),
                                  clientOrderId);
                       params = this->omit(
                           params, ccxt::list{std::string("clientOrderId")});
                     } else {
                       ::setValue(request, std::string("uuid"), id);
                     }
                     response = awaitValue(this->privateGetV1Order(
                         this->extend(request, params)));
                     //
                     //     {
                     //         "uuid": "C0101000003152406454",
                     //         "side": "bid",
                     //         "ord_type": "limit",
                     //         "price": "9500000",
                     //         "state": "wait",
                     //         "market": "KRW-BTC",
                     //         "created_at": "2026-07-04T15:05:46+09:00",
                     //         "volume": "0.001",
                     //         "remaining_volume": "0.001",
                     //         "reserved_fee": "23.75",
                     //         "remaining_fee": "23.75",
                     //         "paid_fee": "0",
                     //         "locked": "9524.75",
                     //         "executed_volume": "0",
                     //         "executed_funds": "0",
                     //         "trades_count": 0,
                     //         "stp_type": "cancel_taker",
                     //         "trades": []
                     //     }
                     //
                     data = response;
                   }
                 } else {
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(
                                 " fetchOrder() requires a symbol argument"))));
                   }
                   ccxt::any marketDefined = market;
                   ccxt::any base =
                       this->safeString(marketDefined, std::string("base"));
                   ccxt::any quote =
                       this->safeString(marketDefined, std::string("quote"));
                   if (isTrue(isTrue((isEqual(base, ccxt::any{}))) ||
                              isTrue((isEqual(quote, ccxt::any{}))))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" fetchOrder() requires a market with "
                                         "defined base and quote"))));
                   }
                   ::setValue(request, std::string("order_id"), id);
                   ::setValue(request, std::string("order_currency"), base);
                   ::setValue(request, std::string("payment_currency"), quote);
                   response = awaitValue(this->privatePostInfoOrderDetail(
                       this->extend(request, params)));
                   //
                   //     {
                   //         "status": "0000",
                   //         "data": {
                   //             "order_date": "1603161798539254",
                   //             "type": "ask",
                   //             "order_status": "Cancel",
                   //             "order_currency": "BTC",
                   //             "payment_currency": "KRW",
                   //             "watch_price": "0",
                   //             "order_price": "13344000",
                   //             "order_qty": "0.0125",
                   //             "cancel_date": "1603161803809993",
                   //             "cancel_type": "사용자취소",
                   //             "contract": [
                   //                 {
                   //                     "transaction_date":
                   //                     "1603161799976383", "price":
                   //                     "13344000", "units": "0.0015",
                   //                     "fee_currency": "KRW",
                   //                     "fee": "0",
                   //                     "total": "20016"
                   //                 }
                   //             ],
                   //         }
                   //     }
                   //
                   data = this->safeDict(response, std::string("data"));
                 }
                 ccxt::any orderData = ccxt::dict{
                     {std::string("order_id"), id},
                 };
                 ccxt::any parsedOrder = this->extend(data, orderData);
                 return this->parseOrder(parsedOrder, market);
               })
        .share();
  }

  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("Pending"), std::string("open")},
        {std::string("Completed"), std::string("closed")},
        {std::string("Cancel"), std::string("canceled")},
        {std::string("wait"), std::string("open")},
        {std::string("watch"), std::string("open")},
        {std::string("done"), std::string("closed")},
        {std::string("cancel"), std::string("canceled")},
        {std::string("progress"), std::string("open")},
    };
    return this->safeString(statuses, status, status);
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    //
    // generation 1: fetchOrder
    //
    //     {
    //         "transaction_date": "1572497603668315",
    //         "type": "bid",
    //         "order_status": "Completed", // Completed, Cancel ...
    //         "order_currency": "BTC",
    //         "payment_currency": "KRW",
    //         "watch_price": "0", // present in Cancel order
    //         "order_price": "8601000",
    //         "order_qty": "0.007",
    //         "cancel_date": "", // filled in Cancel order
    //         "cancel_type": "", // filled in Cancel order, i.e. 사용자취소
    //         "contract": [
    //             {
    //                 "transaction_date": "1572497603902030",
    //                 "price": "8601000",
    //                 "units": "0.005",
    //                 "fee_currency": "KRW",
    //                 "fee": "107.51",
    //                 "total": "43005"
    //             },
    //         ]
    //     }
    //
    // generation 1: fetchOpenOrders
    //
    //     {
    //         "order_currency": "BTC",
    //         "payment_currency": "KRW",
    //         "order_id": "C0101000003152294086",
    //         "order_date": "1783141846061516",
    //         "type": "bid",
    //         "watch_price": "0",
    //         "units": "0.001",
    //         "units_remaining": "0.001",
    //         "price": "9500000",
    //         "stp_type": "cancel_taker"
    //     }
    //
    // generation 1: cancelOrder
    //
    //     {
    //         "status": "0000"
    //     }
    //
    // generation 2: createOrder, createOrders
    //
    //     {
    //         "order_id": "C0101000003152350309",
    //         "market": "KRW-BTC",
    //         "side": "bid",
    //         "order_type": "limit",
    //         "created_at": "2026-07-04T14:39:04+09:00",
    //         "stp_type": "cancel_taker"
    //     }
    //
    // generation 2: fetchOrder, fetchOrders, fetchOpenOrders,
    // fetchClosedOrders, fetchCanceledOrders
    //
    //     {
    //         "uuid": "C0101000003152406454",
    //         "side": "bid",
    //         "ord_type": "limit",
    //         "price": "9500000",
    //         "state": "wait",
    //         "market": "KRW-BTC",
    //         "created_at": "2026-07-04T15:05:46+09:00",
    //         "volume": "0.001",
    //         "remaining_volume": "0.001",
    //         "reserved_fee": "23.75",
    //         "remaining_fee": "23.75",
    //         "paid_fee": "0",
    //         "locked": "9524.75",
    //         "executed_volume": "0",
    //         "executed_funds": "0",
    //         "trades_count": 0,
    //         "stp_type": "cancel_taker",
    //         "trades": []
    //     }
    //
    // generation 2: cancelOrder, cancelOrders
    //
    //     {
    //         "order_id": "C0101000003152350309",
    //         "created_at": "2026-07-04T14:39:04+09:00"
    //     }
    //
    // generation 2: createTwapOrder, twap cancelOrder
    //
    //     {
    //         "algo_order_id": "019f3ed7-4f92-7179-beee-84b4c71e53fa"
    //     }
    //
    // generation 2: twap fetchOrder, fetchOrders, fetchOpenOrders,
    // fetchClosedOrders, fetchCanceledOrders
    //
    //     {
    //         "uuid": "019f3ed7-4f92-7179-beee-84b4c71e53fa",
    //         "side": "bid",
    //         "price": "92500000",
    //         "state": "progress",
    //         "market": "KRW-BTC",
    //         "created_at": "2025-12-03T09:00:00+09:00",
    //         "volume": "1.0",
    //         "total_order_count": 60,
    //         "total_trades_count": 10,
    //         "progress_count": 25,
    //         "total_executed_amount": "2312500000",
    //         "total_executed_volume": "0.25",
    //         "avg_trade_price": "92500000.000",
    //         "wallet_id": "0000000000-00-0000",
    //         "canceled_at": "2025-12-03T09:15:00+09:00",
    //         "cancel_type": "user"
    //     }
    //
    ccxt::any datetime = this->safeString(order, std::string("created_at"));
    ccxt::any timestamp = ccxt::any{};
    if (isTrue(!isEqual(datetime, ccxt::any{}))) {
      if (isTrue(
              isGreaterThan(getIndexOf(datetime, std::string("+09:00")), -1))) {
        ccxt::any normalized =
            replace(datetime, std::string("+09:00"), std::string("Z"));
        ccxt::any normalizedTimestamp = this->parse8601(normalized);
        if (isTrue(!isEqual(normalizedTimestamp, ccxt::any{}))) {
          timestamp = subtract(normalizedTimestamp, multiply(9, 3600000));
        } else {
          timestamp = this->parse8601(datetime);
        }
      } else {
        timestamp = this->parse8601(datetime);
      }
    } else {
      timestamp =
          this->safeIntegerProduct(order, std::string("order_date"), 0.001);
      datetime = this->iso8601(timestamp);
    }
    ccxt::any sideProperty =
        this->safeString2(order, std::string("type"), std::string("side"));
    ccxt::any side = ccxt::any{};
    if (isTrue(isEqual(sideProperty, std::string("bid")))) {
      side = std::string("buy");
    } else if (isTrue(isEqual(sideProperty, std::string("ask")))) {
      side = std::string("sell");
    }
    ccxt::any status = this->parseOrderStatus(this->safeString2(
        order, std::string("order_status"), std::string("state")));
    ccxt::any price = this->safeString2(order, std::string("order_price"),
                                        std::string("price"));
    ccxt::any type = this->safeString2(order, std::string("order_type"),
                                       std::string("ord_type"));
    ccxt::any progressCount =
        this->safeString(order, std::string("progress_count"));
    if (isTrue(isTrue(isTrue((isEqual(type, ccxt::any{}))) &&
                      isTrue((!isEqual(price, ccxt::any{})))) &&
               isTrue((isEqual(progressCount, ccxt::any{}))))) {
      if (isTrue(ccxt::Precise::stringEquals(price, std::string("0")))) {
        type = std::string("market");
      } else {
        type = std::string("limit");
      }
    }
    ccxt::any amount = this->fixCommaNumber(this->safeStringN(
        order, ccxt::list{std::string("order_qty"), std::string("units"),
                          std::string("volume")}));
    ccxt::any remaining = this->fixCommaNumber(
        this->safeString2(order, std::string("units_remaining"),
                          std::string("remaining_volume")));
    if (isTrue(isEqual(remaining, ccxt::any{}))) {
      if (isTrue(isEqual(status, std::string("closed")))) {
        remaining = std::string("0");
      } else if (isTrue(!isEqual(status, std::string("canceled")))) {
        remaining = amount;
      }
    }
    ccxt::any symbol = ccxt::any{};
    ccxt::any baseId = this->safeString(order, std::string("order_currency"));
    ccxt::any quoteId =
        this->safeString(order, std::string("payment_currency"));
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    if (isTrue(isTrue((!isEqual(base, ccxt::any{}))) &&
               isTrue((!isEqual(quote, ccxt::any{}))))) {
      symbol = add(add(base, std::string("/")), quote);
    }
    if (isTrue(isEqual(symbol, ccxt::any{}))) {
      ccxt::any marketId = this->safeString(order, std::string("market"));
      market = this->safeMarket(marketId, market);
      symbol = ::getValue(market, std::string("symbol"));
    }
    ccxt::any id = this->safeStringN(
        order, ccxt::list{std::string("order_id"), std::string("uuid"),
                          std::string("algo_order_id")});
    ccxt::any rawTrades = this->safeList2(order, std::string("contract"),
                                          std::string("trades"), ccxt::list{});
    ccxt::any feeCost = this->safeNumber(order, std::string("reserved_fee"));
    ccxt::any fee = ccxt::any{};
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      ccxt::any currency = ccxt::any{};
      if (isTrue(!isEqual(market, ccxt::any{}))) {
        currency = ::getValue(market, std::string("quote"));
      }
      fee = ccxt::dict{
          {std::string("currency"), currency},
          {std::string("cost"), feeCost},
          {std::string("rate"), ccxt::any{}},
      };
    }
    ccxt::any postOnly = ccxt::any{};
    ccxt::any timeInForce =
        this->safeStringUpper(order, std::string("time_in_force"));
    if (isTrue(isEqual(timeInForce, std::string("POST_ONLY")))) {
      timeInForce = std::string("PO");
      postOnly = true;
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), id},
            {std::string("clientOrderId"),
             this->safeString(order, std::string("client_order_id"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), datetime},
            {std::string("lastTradeTimestamp"), ccxt::any{}},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), postOnly},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"), ccxt::any{}},
            {std::string("amount"), amount},
            {std::string("cost"), ccxt::any{}},
            {std::string("average"),
             this->safeNumber(order, std::string("avg_trade_price"))},
            {std::string("filled"), ccxt::any{}},
            {std::string("remaining"), remaining},
            {std::string("status"), status},
            {std::string("fee"), fee},
            {std::string("trades"), rawTrades},
        },
        market);
  }

  /**
   * @method
   * @name bithumb#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://apidocs.bithumb.com/v1.2.0/reference/%EA%B1%B0%EB%9E%98-%EC%A3%BC%EB%AC%B8%EB%82%B4%EC%97%AD-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%A3%BC%EB%AC%B8-%EB%A6%AC%EC%8A%A4%ED%8A%B8-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/twap-%EC%A3%BC%EB%AC%B8%EB%82%B4%EC%97%AD-%EC%A1%B0%ED%9A%8C
   * @param {string} [symbol] unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of open order structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] if you want to use the API generation 1 or
   * 2, default is 2
   * @param {bool} [params.twap] *generation 2 only* if you want to fetch
   * generation 2 twap orders
   * @param {string} [params.state] *generation 2 only* the order state, either
   * wait, watch, done, or cancel. For twap either progress (default), done, or
   * cancel
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any generation = ccxt::any{};
                ccxt::any generationparamsVariable =
                    this->handleOptionAndParams(params,
                                                std::string("fetchOpenOrders"),
                                                std::string("generation"), 2);
                generation = ::getValue(generationparamsVariable, 0);
                params = ::getValue(generationparamsVariable, 1);
                ccxt::any request = ccxt::dict{};
                ccxt::any market = ccxt::any{};
                ccxt::any response = ccxt::any{};
                if (isTrue(isEqual(generation, 2))) {
                  ccxt::any twap =
                      this->safeBool(params, std::string("twap"), false);
                  if (isTrue(twap)) {
                    ::setValue(params, std::string("state"),
                               std::string("progress"));
                  } else {
                    ::setValue(params, std::string("state"),
                               std::string("wait"));
                  }
                  ccxt::any orders = awaitValue(
                      this->fetchOrders(symbol, since, limit, params));
                  return this->filterBySinceLimit(orders, since, limit);
                } else {
                  if (isTrue(isEqual(symbol, ccxt::any{}))) {
                    throw ArgumentsRequired(toString(add(
                        this->id,
                        std::string(
                            " fetchOpenOrders() requires a symbol argument"))));
                  }
                  market = this->market(symbol);
                  if (isTrue(!isEqual(since, ccxt::any{}))) {
                    ::setValue(request, std::string("after"), since);
                  }
                  if (isTrue(isEqual(limit, ccxt::any{}))) {
                    limit = 100;
                  }
                  ::setValue(request, std::string("count"), limit);
                  ::setValue(request, std::string("order_currency"),
                             ::getValue(market, std::string("base")));
                  ::setValue(request, std::string("payment_currency"),
                             ::getValue(market, std::string("quote")));
                  response = awaitValue(this->privatePostInfoOrders(
                      this->extend(request, params)));
                }
                ccxt::any data =
                    this->safeList(response, std::string("data"), ccxt::list{});
                return this->parseOrders(data, market, since, limit);
              })
            .share();
  }

  /**
   * @method
   * @name bithumb#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://apidocs.bithumb.com/reference/%EC%A3%BC%EB%AC%B8-%EB%A6%AC%EC%8A%A4%ED%8A%B8-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/twap-%EC%A3%BC%EB%AC%B8%EB%82%B4%EC%97%AD-%EC%A1%B0%ED%9A%8C
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string[]} [params.clientOrderIds] an array of client order ids
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @param {bool} [params.twap] *generation 2 only* if you want to fetch
   * generation 2 twap orders
   * @param {string} [params.state] *generation 2 only* the order state, either
   * wait, watch, done, or cancel. For twap either progress (default), done, or
   * cancel
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchOrders"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" fetchOrders is only supported "
                                             "for the generation 2 API"))));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any twap =
                     this->safeBool(params, std::string("twap"), false);
                 params = this->omit(params, std::string("twap"));
                 if (!isTrue(twap)) {
                   ccxt::any clientOrderIds =
                       this->safeList2(params, std::string("client_order_ids"),
                                       std::string("clientOrderIds"));
                   if (isTrue(!isEqual(clientOrderIds, ccxt::any{}))) {
                     ::setValue(request, std::string("client_order_ids"),
                                clientOrderIds);
                     params = this->omit(
                         params, ccxt::list{std::string("clientOrderIds")});
                   }
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              this->getGen2MarketId(market));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any data = ccxt::any{};
                 if (isTrue(twap)) {
                   response = awaitValue(
                       this->privateGetV1Twap(this->extend(request, params)));
                   //
                   //     {
                   //         "has_next": false,
                   //         "next_key": null,
                   //         "orders": [
                   //             {
                   //                 "uuid":
                   //                 "019f3ed7-4f92-7179-beee-84b4c71e53fa",
                   //                 "side": "bid",
                   //                 "price": "92500000",
                   //                 "state": "progress",
                   //                 "market": "KRW-BTC",
                   //                 "created_at": "2025-12-04T10:00:00+09:00",
                   //                 "volume": "1.0",
                   //                 "total_order_count": 60,
                   //                 "total_trades_count": 10,
                   //                 "progress_count": 25,
                   //                 "total_executed_amount": "2312500000",
                   //                 "total_executed_volume": "0.25",
                   //                 "avg_trade_price": "92500000.000",
                   //                 "wallet_id": "0000000000-00-0000"
                   //             },
                   //         ]
                   //     }
                   //
                   data = this->safeList(response, std::string("orders"),
                                         ccxt::list{});
                 } else {
                   response = awaitValue(
                       this->privateGetV1Orders(this->extend(request, params)));
                   //
                   //     [
                   //         {
                   //             "uuid": "C0101000003152406454",
                   //             "side": "bid",
                   //             "ord_type": "limit",
                   //             "price": "9500000",
                   //             "state": "wait",
                   //             "market": "KRW-BTC",
                   //             "created_at": "2026-07-04T15:05:46+09:00",
                   //             "volume": "0.001",
                   //             "remaining_volume": "0.001",
                   //             "reserved_fee": "23.75",
                   //             "remaining_fee": "23.75",
                   //             "paid_fee": "0",
                   //             "locked": "9524.75",
                   //             "executed_volume": "0",
                   //             "executed_funds": "0",
                   //             "trades_count": 0,
                   //             "stp_type": "cancel_taker"
                   //         }
                   //     ]
                   //
                   data = response;
                 }
                 return this->parseOrders(data, market, since, limit);
               })
        .share();
  }

