  /**
   * @method
   * @name bithumb#fetchWithdrawal
   * @description fetch data on a currency withdrawal via the withdrawal id
   * @see
   * https://apidocs.bithumb.com/reference/%EA%B0%9C%EB%B3%84-%EC%B6%9C%EA%B8%88-%EC%A1%B0%ED%9A%8C
   * @param {string} id withdrawal id
   * @param {string} [code] the currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.txid] the transaction id for the withdrawal
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  virtual std::shared_future<ccxt::any>
  fetchWithdrawal(ccxt::any id, ccxt::any code = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchWithdrawal"),
                                                 std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchWithdrawal() is only supported "
                                       "for the generation 2 API"))));
                 }
                 if (isTrue(isEqual(code, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchWithdrawal() requires a code argument"))));
                 }
                 ccxt::any currency = this->currency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 if (isTrue(!isEqual(id, ccxt::any{}))) {
                   ::setValue(request, std::string("uuid"), id);
                 }
                 ccxt::any response = awaitValue(
                     this->privateGetV1Withdraw(this->extend(request, params)));
                 //
                 //     {
                 //         "type": "withdraw",
                 //         "uuid": "200377211",
                 //         "currency": "BTC",
                 //         "net_type": "BTC",
                 //         "state": "processing",
                 //         "created_at": "2024-07-14T14:54:24+09:00",
                 //         "done_at": null,
                 //         "amount": "0.00010000",
                 //         "fee": "0",
                 //         "transaction_type": null,
                 //         "txid": null
                 //     }
                 //
                 return this->parseTransaction(response, currency);
               })
        .share();
  }

  /**
   * @method
   * @name bithumb#fetchWithdrawals
   * @description fetch all withdrawals made from an account
   * @see
   * https://apidocs.bithumb.com/reference/%EC%B6%9C%EA%B8%88-%EB%A6%AC%EC%8A%A4%ED%8A%B8-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%9B%90%ED%99%94-%EC%B6%9C%EA%B8%88-%EB%A6%AC%EC%8A%A4%ED%8A%B8-%EC%A1%B0%ED%9A%8C
   * @param {string} [code] unified currency code
   * @param {int} [since] the earliest time in ms to fetch withdrawals for
   * @param {int} [limit] the maximum number of withdrawals to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @param {int} [params.page] the number of pages to return, default is 1
   * @param {string} [params.state] the withdrawal state, either PROCESSING,
   * DONE or CANCELLED
   * @param {string} [params.order_by] either asc or desc, desc is the default
   * @param {string[]} [params.uuids] an array of uuid strings
   * @param {string[]} [params.txids] an array of txid strings
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchWithdrawals(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                   ccxt::any limit = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchWithdrawals"),
                         std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchWithdrawals() is only supported "
                                       "for the generation 2 API"))));
                 }
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any currency = ccxt::any{};
                 if (isTrue(isEqual(code, std::string("KRW")))) {
                   currency = this->currency(code);
                   response = awaitValue(this->privateGetV1WithdrawsKrw(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(!isEqual(code, ccxt::any{}))) {
                     currency = this->currency(code);
                     ::setValue(request, std::string("currency"),
                                ::getValue(currency, std::string("id")));
                   }
                   response = awaitValue(this->privateGetV1Withdraws(
                       this->extend(request, params)));
                 }
                 //
                 //     [
                 //         {
                 //             "type": "withdraw",
                 //             "uuid": "200377211",
                 //             "currency": "BTC",
                 //             "net_type": "BTC",
                 //             "state": "processing",
                 //             "created_at": "2024-07-14T14:54:24+09:00",
                 //             "done_at": null,
                 //             "amount": "0.00010000",
                 //             "fee": "0",
                 //             "transaction_type": null,
                 //             "txid": null
                 //         }
                 //     ]
                 //
                 return this->parseTransactions(response, currency, since,
                                                limit);
               })
        .share();
  }

