  /**
   * @method
   * @name bithumb#fetchDeposits
   * @description fetch all deposits made to an account
   * @see
   * https://apidocs.bithumb.com/reference/%EC%9E%85%EA%B8%88-%EB%A6%AC%EC%8A%A4%ED%8A%B8-%EC%A1%B0%ED%9A%8C
   * @see
   * https://apidocs.bithumb.com/reference/%EC%9B%90%ED%99%94-%EC%9E%85%EA%B8%88-%EB%A6%AC%EC%8A%A4%ED%8A%B8-%EC%A1%B0%ED%9A%8C
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of deposits to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @param {int} [params.page] the number of pages to return, default is 1
   * @param {string} [params.state] the deposit state, for KRW, PROCESSING,
   * ACCEPTED or CANCELLED, for others, DEPOSIT_PROCESSING, DEPOSIT_ACCEPTED,
   * DEPOSIT_CANCELLED
   * @param {string} [params.order_by] either asc or desc, desc is the default
   * @param {string[]} [params.uuids] an array of uuid strings
   * @param {string[]} [params.txids] an array of txid strings
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchDeposits(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any generation = ccxt::any{};
                        ccxt::any generationparamsVariable =
                            this->handleOptionAndParams(
                                params, std::string("fetchDeposits"),
                                std::string("generation"), 2);
                        generation = ::getValue(generationparamsVariable, 0);
                        params = ::getValue(generationparamsVariable, 1);
                        if (isTrue(!isEqual(generation, 2))) {
                          throw BadRequest(toString(add(
                              this->id,
                              std::string(" fetchDeposits() is only supported "
                                          "for the generation 2 API"))));
                        }
                        ccxt::any request = ccxt::dict{};
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("limit"), limit);
                        }
                        ccxt::any response = ccxt::any{};
                        ccxt::any currency = ccxt::any{};
                        if (isTrue(isEqual(code, std::string("KRW")))) {
                          currency = this->currency(code);
                          response = awaitValue(this->privateGetV1DepositsKrw(
                              this->extend(request, params)));
                        } else {
                          if (isTrue(!isEqual(code, ccxt::any{}))) {
                            currency = this->currency(code);
                            ::setValue(request, std::string("currency"),
                                       ::getValue(currency, std::string("id")));
                          }
                          response = awaitValue(this->privateGetV1Deposits(
                              this->extend(request, params)));
                        }
                        //
                        //     [
                        //         {
                        //             "type": "deposit",
                        //             "uuid": "200377211",
                        //             "currency": "BTC",
                        //             "net_type": "BTC",
                        //             "state": "DEPOSIT_ACCEPTED",
                        //             "created_at":
                        //             "2024-07-14T14:54:24+09:00", "done_at":
                        //             null, "amount": "0.00010000", "fee": "0",
                        //             "transaction_type": null,
                        //             "txid": null
                        //         }
                        //     ]
                        //
                        return this->parseTransactions(response, currency,
                                                       since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name bithumb#createDepositAddress
   * @description create a currency deposit address
   * @see
   * https://apidocs.bithumb.com/reference/%EC%9E%85%EA%B8%88-%EC%A3%BC%EC%86%8C-%EC%83%9D%EC%84%B1-%EC%9A%94%EC%B2%AD
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.generation] *only generation 2 is supported* if you
   * want to use the API generation 1 or 2, default is 2
   * @param {string} [params.network] the blockchain network to create a deposit
   * address on
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<ccxt::any>
  createDepositAddress(ccxt::any code,
                       ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any generation = ccxt::any{};
                 ccxt::any generationparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("createDepositAddress"),
                         std::string("generation"), 2);
                 generation = ::getValue(generationparamsVariable, 0);
                 params = ::getValue(generationparamsVariable, 1);
                 if (isTrue(!isEqual(generation, 2))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" createDepositAddress() is only "
                                       "supported for the generation 2 API"))));
                 }
                 ccxt::any currency = this->currency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 ccxt::any network = this->safeString2(
                     params, std::string("network"), std::string("net_type"));
                 params = this->omit(params, std::string("network"));
                 if (isTrue(isEqual(network, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(add(add(this->id, std::string(" ")), code),
                           std::string(" createDepositAddress() requires a "
                                       "network parameter"))));
                 }
                 ::setValue(request, std::string("net_type"), network);
                 ccxt::any response =
                     awaitValue(this->privatePostV1DepositsGenerateCoinAddress(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "currency": "BTC",
                 //         "net_type": "BTC",
                 //         "deposit_address": "195Y...rbJ3",
                 //         "secondary_address": null
                 //     }
                 //
                 return this->parseDepositAddress(response, currency);
               })
        .share();
  }

